<?php
get_header();
$selected = array('linha' => fort_input('linha'), 'ambiente' => fort_input('ambiente'), 'acabamento' => fort_input('acabamento'));
$taxonomies = array('linha' => 'fort_linha', 'ambiente' => 'fort_ambiente', 'acabamento' => 'fort_acabamento');
$tax_query = array('relation' => 'AND');
if (is_tax(array_values($taxonomies))) { $current = get_queried_object(); foreach ($taxonomies as $param => $taxonomy) if ($taxonomy === $current->taxonomy) $selected[$param] = $current->slug; }
foreach ($taxonomies as $param => $taxonomy) if ($selected[$param]) $tax_query[] = array('taxonomy' => $taxonomy, 'field' => 'slug', 'terms' => $selected[$param]);
$query = fort_products_query(12, array('tax_query' => $tax_query, 'fort_catalog_search' => fort_input('q'), 'paged' => max(1, absint(get_query_var('paged')))));
?>
<main id="conteudo"><section class="page-intro"><div class="container"><div class="breadcrumb"><a href="<?php echo esc_url(home_url('/')); ?>">Início</a><?php echo fort_icon('chevron'); ?><span>Produtos</span></div><span class="eyebrow">CATÁLOGO FORT METAIS</span><h1>Seu estilo, em cada detalhe.</h1><p>Encontre os metais que combinam com seu ambiente e seu projeto.</p></div></section>
<section class="section container catalog-section"><form class="catalog-filters" action="<?php echo esc_url(fort_catalog_url()); ?>" method="get"><div class="filter-search"><label for="catalog-q">Busque um produto</label><div class="search-field"><?php echo fort_icon('search'); ?><input type="search" name="q" id="catalog-q" value="<?php echo esc_attr(fort_input('q')); ?>" placeholder="Nome ou referência"></div></div>
<?php foreach (array('linha' => 'Linha', 'ambiente' => 'Ambiente', 'acabamento' => 'Acabamento') as $param => $label): ?><div><label for="filter-<?php echo esc_attr($param); ?>"><?php echo esc_html($label); ?></label><select id="filter-<?php echo esc_attr($param); ?>" name="<?php echo esc_attr($param); ?>"><option value=""><?php echo $param === 'linha' ? 'Todas as linhas' : ($param === 'ambiente' ? 'Todos os ambientes' : 'Todos os acabamentos'); ?></option><?php $terms = get_terms(array('taxonomy' => $taxonomies[$param], 'hide_empty' => false)); if (!is_wp_error($terms)) foreach ($terms as $term): ?><option value="<?php echo esc_attr($term->slug); ?>" <?php selected($selected[$param], $term->slug); ?>><?php echo esc_html($term->name); ?></option><?php endforeach; ?></select></div><?php endforeach; ?><button class="button button-small" type="submit">Filtrar <?php echo fort_icon('arrow'); ?></button></form>
<div class="catalog-summary"><p><strong><?php echo esc_html($query->found_posts); ?></strong> <?php echo $query->found_posts === 1 ? 'produto encontrado' : 'produtos encontrados'; ?></p><?php if (array_filter($selected) || fort_input('q')): ?><a class="text-link" href="<?php echo esc_url(fort_catalog_url()); ?>">Limpar filtros <?php echo fort_icon('close'); ?></a><?php endif; ?></div>
<?php if ($query->have_posts()): ?><div class="product-grid"><?php while ($query->have_posts()): $query->the_post(); fort_product_card(); endwhile; ?></div><nav class="pagination" aria-label="Páginas do catálogo"><?php echo wp_kses_post(paginate_links(array('total' => $query->max_num_pages, 'current' => max(1, absint(get_query_var('paged'))), 'prev_text' => 'Anterior', 'next_text' => 'Próxima', 'add_args' => array_filter(array_merge($selected, array('q' => fort_input('q')))))) ?: ''); ?></nav><?php else: ?><div class="empty-state"><?php echo fort_icon('search'); ?><h2>Vamos tentar outra combinação?</h2><p>Nenhum produto foi encontrado com estes filtros. Explore as outras linhas ou fale com nossa equipe.</p><a class="button" href="<?php echo esc_url(fort_catalog_url()); ?>">Ver todos os produtos <?php echo fort_icon('arrow'); ?></a></div><?php endif; wp_reset_postdata(); ?></section><?php get_template_part('parts/commercial-cta'); ?></main><?php get_footer(); ?>
